(() => {
  const cards = [...document.querySelectorAll('.p6-d3-reveal-card')];
  const vis = cards.filter(c => { const a = c.querySelector('.p6-d3-card-answer'); return a && Number(getComputedStyle(a).opacity) > 0.9; });
  if (!vis.length) return { pass: false, detail: 'لا بطاقة مكشوفة للقياس — السيناريو لم يصل إلى الحالة المطلوبة' };
  const clips = [], hairs = [];
  vis.forEach((c, i) => {
    const pill = c.querySelector('.p6-d3-lc-name'), glyph = c.querySelector('.p6-d3-lc-char');
    const cs = getComputedStyle(c), cr = c.getBoundingClientRect();
    if (!pill) { clips.push(`#${i + 1} لا كبسولة`); return; }
    const txt = pill.textContent.trim();
    const clipTop = cr.top + parseFloat(cs.borderTopWidth);
    const clipBottom = cr.bottom - parseFloat(cs.borderBottomWidth);
    const pr = pill.getBoundingClientRect();
    if (pill.scrollHeight > pill.clientHeight + 2) clips.push(`#${i + 1} «${txt}» مقصوص رأسياً: ${pill.clientHeight}px ظاهر من ${pill.scrollHeight}px`);
    if (pill.scrollWidth > pill.clientWidth + 1) clips.push(`#${i + 1} «${txt}» مقصوص أفقياً`);
    const over = Math.max(pr.bottom - clipBottom, clipTop - pr.top);
    if (over > 2) clips.push(`#${i + 1} الكبسولة خارج منطقة البطاقة بمقدار ${over.toFixed(1)}px`);
    else if (over > 0) hairs.push(`#${i + 1} تجاوز شعري ${over.toFixed(1)}px`);
    if (glyph && glyph.getBoundingClientRect().bottom > pr.top + 1) clips.push(`#${i + 1} الحرف يتراكب مع الكبسولة`);
  });
  if (clips.length) return { pass: false, detail: clips.join(' · ') };
  if (hairs.length) return { pass: false, warn: true, detail: hairs.join(' · ') };
  return { pass: true, detail: `${vis.length} بطاقة سليمة` };
})()

